solve:{[strings]
    n:count strings;
    if[n=0; :0];
    if[n=1; :count first strings];
    min_len:min count each strings;
    i:0;
    while[i<min_len;
        char:first strings[0;i];
        j:1;
        while[j<n;
            if[not strings[j;i]=char; :i];
            j+:1];
        i+:1];
    :i}

solve:{[strings]
    n:count strings;
    if[n=0; :""];
    prefix:first strings;
    i:1;
    while[i<n;
        j:0;
        temp:"";
        while[j<count prefix;
            if[prefix[j]=strings[i;j];
                temp,:prefix[j]];
            if[not prefix[j]=strings[i;j]; :temp];
            j+:1];
        prefix:temp;
        i+:1];
    :prefix}
